from mcp.server.fastmcp import FastMCP
mcp = FastMCP('recruiting')

def _coerce(value):
    try:
        return float(value)
    except (TypeError, ValueError):
        return value

def _normalize_row(row):
    return {k.strip().lower().replace(' ', '_'): _coerce(v) for k, v in row.items()}

@mcp.tool()
def filter_candidates_by_expression(csv_path: str, condition: str) -> list:
    matches = []
    with open(csv_path, newline='', encoding='utf-8') as f:
        for row in csv.DictReader(f):
            env = _normalize_row(row)
            try:
                if eval(condition, {}, env):
                    matches.append(row.get('name', ''))
            except Exception:
                continue
    return matches

