from langchain_core.tools import tool

def _list_pods(namespace):
    out = subprocess.run(['kubectl', 'get', 'pods', '-n', namespace, '-o', 'json'], capture_output=True, text=True, check=True).stdout
    return json.loads(out)['items']

@tool
def filter_pods_by_expression(namespace: str, filter_expr: str) -> str:
    matched = []
    for pod in _list_pods(namespace):
        statuses = pod['status'].get('containerStatuses', [])
        env = {'name': pod['metadata']['name'], 'phase': pod['status'].get('phase'), 'restarts': sum((c['restartCount'] for c in statuses))}
