from mcp.server.fastmcp import FastMCP
mcp = FastMCP('k8s-ops')

def _kubectl(*args):
    return subprocess.run(['kubectl', *args], capture_output=True, text=True, check=True).stdout.strip()

@mcp.tool()
def scale_deployment_by_formula(deployment: str, namespace: str, formula: str) -> str:
    current = int(_kubectl('get', 'deployment', deployment, '-n', namespace, '-o', 'jsonpath={.spec.replicas}'))
    nodes = len(_kubectl('get', 'nodes', '-o', 'name').splitlines())
    scope = {'current': current, 'nodes': nodes}
    target = int(eval(formula, {'__builtins__': {}}, scope))
    target = max(target, 0)
    _kubectl('scale', f'deployment/{deployment}', '-n', namespace, f'--replicas={target}')
    return f'Scaled {deployment} from {current} to {target}'

