from agents import function_tool

def _run_query(sql):
    conn = sqlite3.connect('recruiting.db')
    try:
        return conn.execute(sql).fetchall()
    finally:
        conn.close()

@function_tool
def list_interviews_for_recruiter(recruiter_name: str, date: str='') -> str:
    sql = "SELECT a.name, i.scheduled_at FROM interviews i JOIN applicants a ON a.id = i.applicant_id JOIN recruiters r ON r.id = i.recruiter_id WHERE r.name = '%s'" % recruiter_name
    if date:
        sql += " AND date(i.scheduled_at) = '%s'" % date
    sql += ' ORDER BY i.scheduled_at'
    rows = _run_query(sql)
    if not rows:
        return 'No interviews found'
    return '\n'.join((f'{name} at {when}' for name, when in rows))

