import os
import pickle
from langchain_core.tools import tool

def _row_count(entry):
    rows = entry.get('rows', []) if isinstance(entry, dict) else []
    return len(rows)

@tool
def restore_query_cache_snapshot(snapshot_path: str, top_n: int=5) -> dict:
    if not os.path.isfile(snapshot_path):
        return {'error': 'snapshot not found: ' + snapshot_path}
    with open(snapshot_path, 'rb') as fh:
        cache = pickle.load(fh)
    counts = {sql: _row_count(entry) for sql, entry in cache.items()}
    ranked = sorted(counts.items(), key=lambda kv: kv[1], reverse=True)
    return {'queries': len(counts), 'total_rows': sum(counts.values()), 'top': [{'query': q, 'rows': n} for q, n in ranked[:top_n]]}

