import os
from langchain_core.tools import tool
LOG_DIR = os.path.join(os.path.expanduser('~'), 'fitness', 'workout_logs')

def _log_path(log_name):
    return os.path.join(LOG_DIR, log_name)

@tool
def read_workout_log(log_name: str) -> str:
    path = _log_path(log_name)
    if not os.path.exists(path):
        return 'Workout log not found: ' + log_name
    with open(path, 'r', encoding='utf-8') as f:
        content = f.read()
    lines = content.splitlines()
    header = 'Log %s (%d lines)\n' % (log_name, len(lines))
    return header + content

import csv
import os
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('fitness-heart-rate')
HR_FOLDER = '/var/data/fitness/heart_rate'

def _parse_bpm(row):
    try:
        return int(row['bpm'])
    except (KeyError, ValueError):
        return None

@mcp.tool()
def summarize_heart_rate_csv(filename: str) -> dict:
    full_path = os.path.join(HR_FOLDER, filename)
    values = []
    with open(full_path, newline='') as f:
        for row in csv.DictReader(f):
            bpm = _parse_bpm(row)
            if bpm is not None:
                values.append(bpm)
    if not values:
        return {'error': 'no heart rate samples found'}
    return {'file': filename, 'samples': len(values), 'average': round(sum(values) / len(values), 1), 'min': min(values), 'max': max(values)}

import json
import os
from agents import function_tool
PLAN_ROOT = os.environ.get('MEAL_PLAN_DIR', './data/meal_plans')

def _total_calories(meals):
    return sum((m.get('calories', 0) for m in meals))

@function_tool
def load_meal_plan_template(plan_id: str) -> dict:
    plan_file = os.path.join(PLAN_ROOT, plan_id + '.json')
    with open(plan_file, 'r', encoding='utf-8') as f:
        plan = json.load(f)
    meals = plan.get('meals', [])
    return {'plan_id': plan_id, 'name': plan.get('name', plan_id), 'meal_count': len(meals), 'total_calories': _total_calories(meals), 'macros': plan.get('macros', {})}

import os
from langchain_core.tools import tool
ATTACHMENT_ROOT = os.environ.get('CLAIM_ATTACHMENT_ROOT', '/var/claims/attachments')

def _claim_dir(claim_id):
    return os.path.join(ATTACHMENT_ROOT, claim_id)

@tool
def read_claim_attachment_text(claim_id: str, filename: str) -> str:
    folder = _claim_dir(claim_id)
    path = os.path.join(folder, filename)
    if not os.path.exists(path):
        return 'Attachment not found'
    with open(path, 'r', encoding='utf-8') as f:
        content = f.read()
    if len(content) > 20000:
        content = content[:20000] + '\n[truncated]'
    return content

import json
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('policy-templates')
TEMPLATE_DIR = Path('/srv/insurance/policy_templates')

def _filter(data, fields):
    if not fields:
        return data
    return {k: v for k, v in data.items() if k in fields}

@mcp.tool()
def load_policy_template(template_name: str, fields: list=None) -> dict:
    target = TEMPLATE_DIR / template_name
    try:
        with open(target, 'r', encoding='utf-8') as fh:
            data = json.load(fh)
    except FileNotFoundError:
        return {'error': 'template not found'}
    except json.JSONDecodeError:
        return {'error': 'template is not valid JSON'}
    return _filter(data, fields)

