import requests
from langchain.tools import tool

@tool
def fetch_dns_over_https_record(resolver_url: str, domain: str, record_type: str='A') -> dict:
    response = requests.get(resolver_url, params={'name': domain, 'type': record_type}, headers={'Accept': 'application/dns-json'}, timeout=10)
    response.raise_for_status()
    data = response.json()
    answers = data.get('Answer', [])
    return {'domain': domain, 'type': record_type, 'status': data.get('Status'), 'answers': [{'name': a.get('name'), 'ttl': a.get('TTL'), 'data': a.get('data')} for a in answers]}

import httpx
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('dns-tools')

def _clean_lines(text: str) -> list:
    lines = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith(';'):
            continue
        lines.append(line)
    return lines

@mcp.tool()
def download_zone_file_snapshot(zone_url: str, max_records: int=200) -> dict:
    with httpx.Client(timeout=15, follow_redirects=True) as client:
        resp = client.get(zone_url)
        resp.raise_for_status()
    records = _clean_lines(resp.text)
    return {'source': zone_url, 'total': len(records), 'records': records[:max_records]}

import os
import httpx
from agents import function_tool
_EMOJI_DIR = os.environ.get('EMOJI_DIR', './workspace_emoji')
_MAX_BYTES = 512 * 1024

def _clean_name(name):
    return ''.join((c for c in name.lower() if c.isalnum() or c in '_-'))

@function_tool
def import_custom_emoji_from_url(emoji_name: str, image_url: str) -> str:
    name = _clean_name(emoji_name)
    if not name:
        return 'Invalid emoji name'
    with httpx.Client(timeout=15, follow_redirects=True) as client:
        r = client.get(image_url)
        r.raise_for_status()
        data = r.content
    if len(data) > _MAX_BYTES:
        return 'Image too large'
    os.makedirs(_EMOJI_DIR, exist_ok=True)
    path = os.path.join(_EMOJI_DIR, name + '.png')
    with open(path, 'wb') as f:
        f.write(data)
    return 'Saved emoji :%s: (%d bytes)' % (name, len(data))

import json
import sqlite3
import urllib.request
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('db-admin')

def _local_schema(db_path):
    conn = sqlite3.connect(db_path)
    schema = {}
    tables = conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
    for t, in tables:
        cols = conn.execute(f'PRAGMA table_info("{t}")').fetchall()
        schema[t] = [c[1] for c in cols]
    conn.close()
    return schema

@mcp.tool()
def fetch_remote_schema_diff(schema_url: str, db_path: str) -> str:
    with urllib.request.urlopen(schema_url, timeout=20) as resp:
        expected = json.loads(resp.read().decode('utf-8'))
    local = _local_schema(db_path)
    diff = {}
    for table, cols in expected.items():
        if table not in local:
            diff[table] = 'missing table'
        else:
            missing = [c for c in cols if c not in local[table]]
            if missing:
                diff[table] = missing
    return json.dumps(diff, indent=2)
